// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts, address actor) public {
        // keep the domain admissible: fresh contract has pastBlockTime == 0,
        // and pastBlockTime = ts + 1 must not overflow
        uint256 number = bound(blockNum, 0, type(uint256).max);
        uint256 timestamp = bound(ts, 1, type(uint256).max - 1);
        vm.assume(actor != address(0) && actor != address(c));

        vm.roll(number);
        vm.warp(timestamp);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok, "call should succeed for admissible input");

        // general rule: funds are paid out iff and only if block.number % 15 == 0
        bool drained = address(c).balance == 0;
        bool shouldDrain = (number % 15 == 0);
        assertTrue(drained == shouldDrain, "payout condition violated");
    }
}
